import React, { useEffect } from "react";

export default function CreateTicket() {



 
    async function createTicket(event) {
        event.preventDefault();

        try {

            const response = await fetch("http://localhost:3001/createTicket/:id", {
                method: "POST",
                headers: {
                    "Authorization": `Bearer ${token}`,
                },
                body: JSON.stringify({
                    "title" : title,
                    "place" : place,
                    "description" : description,
                    "urgent_id": Number(urgent_id)
                })
            });

            const data = await response.json();

            if(!response.ok) {
                alert(`Nem sikerült a hibajegy létrehozása: ${data.message}`)
            } else {
                alert("Sikeres hibajegy létrehozása");
            }
 
        } catch (err){
                console.error("Hiba történt a hibajegy létrehozása során:", err);
            }
            
    }

    return (
         <form className="container" onSubmit={createTicket}>
                 <div className="mb-3">
                      <label for="username" className="form-label">Felhasználónév</label>
                      <input type="text" className="form-control" id="username" required/>        
                </div>
                 <div className="mb-3">
                    <label for="email" className="form-label">E-mail cím</label>
                        <input type="email" className="form-control" id="email" required/>
                </div>
                <div className="mb-3">
                    <label for="password" className="form-label">Jelszó</label>
                        <input type="password" className="form-control" id="password" required/>
                </div>
                  <div className="mb-3">
                   <select className="form-select" aria-label="Default select example"
                   id="role_id" required>
                        <option selected>Jogkör kiválasztása</option>
                        <option value="1">Administrtátor</option>
                        <option value="2">Manager</option>
                        <option value="3">Személyzet</option>
                        <option value="4">Dolgozó</option>
                </select>
                </div>                    
                <button type="submit" className="btn btn-primary">Új felhasználó regisztrálása </button>
    </form>
    )
    
}
